class Solution {
    public int rob(int[] nums) {
        return f(nums, 0);
    }

    private int f(int[] nums, int i) {
        if (i >= nums.length) return 0;
        int skip = f(nums, i + 1);
        int take = nums[i] + f(nums, i + 2);
        return Math.max(skip, take);
    }
}

class Solution {
    public int rob(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        int[] dp = new int[n + 1];
        dp[0] = 0;
        dp[1] = nums[0];
        for (int i = 2; i <= n; i++) {
            dp[i] = Math.max(dp[i - 1], nums[i - 1] + dp[i - 2]);
        }
        return dp[n];
    }
}

class Solution {
    public int rob(int[] nums) {
        int prev2 = 0;
        int prev1 = 0;
        for (int i = 1; i <= nums.length; i++) {
            int cur = Math.max(prev1, nums[i - 1] + prev2);
            prev2 = prev1;
            prev1 = cur;
        }
        return prev1;
    }
}
